/* ============================================
   ACTION READOUT COMPONENT
   What a confirmed change did: a title over
   a two-column list of facts, label beside
   value. A content card of the chat furniture,
   on ActionCard's surface, so a proposal and
   its readout read as one family.
   ============================================ */

.ds-action-readout {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
  width: 100%;
  min-width: 0;
  padding: var(--padding-300);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  background-color: var(--color-bg-container-primary);
}

.ds-action-readout__title {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-action-readout__icon {
  display: inline-flex;
  flex-shrink: 0;
  --icon-size: var(--icon-size-500);
}

.ds-action-readout__facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  column-gap: var(--gap-400);
  row-gap: var(--gap-100);
  margin: 0;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-action-readout__facts dt {
  color: var(--color-text-secondary);
}

.ds-action-readout__facts dd {
  margin: 0;
  color: var(--color-text-primary);
  overflow-wrap: anywhere;
}

.ds-action-readout .material-symbols-rounded {
  color: inherit;
}

import React from 'react';
import './ActionReadout.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';

/** One line of a readout: what it measures and its value, already written in the reader's locale. */
export interface ActionReadoutFact {
  /** What it measures: "Refunded". */
  label: string;
  /** Its value: "$101,137 across 52 orders". */
  value: React.ReactNode;
}

/** Props owned by ActionReadout itself — everything else falls through to the root `<div>`. */
type ActionReadoutOwnProps = {
  /** What was done, with how much: "69 orders cancelled". Collides with the native `title` tooltip attribute on purpose: the readout shows it. */
  title: React.ReactNode;
  /** What it did, a line each: the status it moved, the money it touched, who it reached. */
  facts: ActionReadoutFact[];
  /** A leading mark beside the title: a Material Symbol name, or your own element. */
  icon?: string | React.ReactNode;
  /** Additional CSS classes */
  className?: string;
};

export interface ActionReadoutProps
  extends ActionReadoutOwnProps,
    Omit<React.ComponentPropsWithRef<'div'>, keyof ActionReadoutOwnProps> {}

const baseClass = 'ds-action-readout';

/**
 * What a confirmed change did, as the opening of the reply its confirmation
 * gets: a title over a list of facts, worked out by the host from the
 * records as they were just before the change, so it is exact without a model.
 * The facts are a description list, so each label is read with its value.
 */
export function ActionReadout({ ref, title, facts, icon, className = '', ...rest }: ActionReadoutProps) {
  return (
    <div {...rest} ref={ref} className={[baseClass, className].filter(Boolean).join(' ')}>
      <span className={`${baseClass}__title`}>
        {icon && (
          <span className={`${baseClass}__icon`} aria-hidden="true">
            {typeof icon === 'string' ? <span className={`material-symbols-rounded ${mirrorClass(icon)}`}>{icon}</span> : icon}
          </span>
        )}
        {title}
      </span>
      <dl className={`${baseClass}__facts`}>
        {facts.map((fact) => (
          <React.Fragment key={fact.label}>
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </React.Fragment>
        ))}
      </dl>
    </div>
  );
}
